// Mini template renderer — dependency-free, for Bun.
// Public API: render(template, data) -> string

export type RenderContext = {
  current: unknown;
  root: unknown;
  index: number | undefined;
};

type Token = {
  type: "text" | "interp" | "raw" | "comment" | "open_block" | "else" | "close_block";
  content: string;
  text?: string;
  line: number;
  col: number;
};

type Node =
  | { kind: "text"; text: string }
  | { kind: "interp"; path: string; escaped: boolean; line: number; col: number }
  | { kind: "if"; path: string; children: Node[]; elseChildren: Node[] | null; line: number; col: number }
  | { kind: "each"; path: string; children: Node[]; elseChildren: Node[] | null; line: number; col: number };

// ---------- Tokenizer ----------

function tokenize(src: string): Token[] {
  const tokens: Token[] = [];
  const n = src.length;
  let i = 0;
  let line = 1;
  let col = 1;

  const advance = (end: number): string => {
    const slice = src.slice(i, end);
    for (let k = 0; k < slice.length; k++) {
      if (slice[k] === "\n") {
        line++;
        col = 1;
      } else {
        col++;
      }
    }
    i = end;
    return slice;
  };

  while (i < n) {
    if (src[i] === "{" && src[i + 1] === "{") {
      const startLine = line;
      const startCol = col;
      const triple = src[i + 2] === "{";

      if (triple) {
        const end = src.indexOf("}}}", i + 3);
        if (end === -1) {
          throw new Error(`Unclosed triple-brace tag at line ${startLine}, column ${startCol}`);
        }
        const content = src.slice(i + 3, end).trim();
        advance(end + 3);
        tokens.push({ type: "raw", content, line: startLine, col: startCol });
      } else {
        const end = src.indexOf("}}", i + 2);
        if (end === -1) {
          throw new Error(`Unclosed tag at line ${startLine}, column ${startCol}`);
        }
        const raw = src.slice(i + 2, end);
        const content = raw.trim();
        advance(end + 2);

        if (content.startsWith("!")) {
          tokens.push({ type: "comment", content, line: startLine, col: startCol });
        } else if (content.startsWith("#")) {
          tokens.push({ type: "open_block", content, line: startLine, col: startCol });
        } else if (content.startsWith("/")) {
          tokens.push({ type: "close_block", content, line: startLine, col: startCol });
        } else if (content === "else") {
          tokens.push({ type: "else", content, line: startLine, col: startCol });
        } else {
          tokens.push({ type: "interp", content, line: startLine, col: startCol });
        }
      }
    } else {
      // accumulate literal text up to the next "{{"
      const next = src.indexOf("{{", i);
      const end = next === -1 ? n : next;
      const text = advance(end);
      tokens.push({ type: "text", content: "", text, line: startLineUnused(text, line), col });
    }
  }

  return tokens;
}

// line/col for text tokens are approximate (start of the run); not used for errors.
function startLineUnused(_text: string, l: number): number {
  return l;
}

// ---------- Parser ----------

type ParseResult = { nodes: Node[]; stop: Token | null };

function parse(tokens: Token[]): Node[] {
  let pos = 0;

  function parseSequence(): ParseResult {
    const nodes: Node[] = [];
    while (pos < tokens.length) {
      const t = tokens[pos];
      if (t.type === "text") {
        if (t.text) nodes.push({ kind: "text", text: t.text });
        pos++;
      } else if (t.type === "comment") {
        pos++;
      } else if (t.type === "interp") {
        nodes.push({ kind: "interp", path: t.content, escaped: true, line: t.line, col: t.col });
        pos++;
      } else if (t.type === "raw") {
        nodes.push({ kind: "interp", path: t.content, escaped: false, line: t.line, col: t.col });
        pos++;
      } else if (t.type === "open_block") {
        const m = t.content.match(/^#(if|each)\s+(.*)$/);
        if (!m) {
          const name = t.content.replace(/^#/, "").trim() || "(empty)";
          throw new Error(`Unknown block "{{#${name}}}" at line ${t.line}, column ${t.col}`);
        }
        const blockType = m[1] as "if" | "each";
        const path = m[2].trim();
        if (!path) {
          throw new Error(`Missing path for "{{#${blockType}}}" at line ${t.line}, column ${t.col}`);
        }
        const openToken = t;
        pos++;

        const childResult = parseSequence();
        let elseChildren: Node[] | null = null;

        if (childResult.stop && childResult.stop.type === "else") {
          pos++; // consume else
          const elseResult = parseSequence();
          elseChildren = elseResult.nodes;
          if (elseResult.stop && elseResult.stop.type === "else") {
            throw new Error(
              `Duplicate {{else}} at line ${elseResult.stop.line}, column ${elseResult.stop.col}`,
            );
          }
          childResult.stop = elseResult.stop;
        }

        if (!childResult.stop || childResult.stop.type !== "close_block") {
          throw new Error(
            `Unclosed block "{{#${blockType} ${path}}}" opened at line ${openToken.line}, column ${openToken.col}`,
          );
        }

        const closeToken = childResult.stop;
        const closeM = closeToken.content.match(/^\/(if|each)$/);
        if (!closeM) {
          const closeName = closeToken.content.replace(/^\//, "").trim();
          throw new Error(
            `Mismatched close "{{/${closeName}}}" at line ${closeToken.line}, column ${closeToken.col}`,
          );
        }
        if (closeM[1] !== blockType) {
          throw new Error(
            `Mismatched block: "{{#${blockType}}}" opened at line ${openToken.line}, column ${openToken.col} but closed with "{{/${closeM[1]}}}" at line ${closeToken.line}, column ${closeToken.col}`,
          );
        }
        pos++; // consume close

        nodes.push({
          kind: blockType,
          path,
          children: childResult.nodes,
          elseChildren,
          line: openToken.line,
          col: openToken.col,
        });
      } else if (t.type === "else") {
        return { nodes, stop: t };
      } else if (t.type === "close_block") {
        return { nodes, stop: t };
      } else {
        pos++;
      }
    }
    return { nodes, stop: null };
  }

  const result = parseSequence();
  if (result.stop) {
    if (result.stop.type === "else") {
      throw new Error(
        `{{else}} outside of a block at line ${result.stop.line}, column ${result.stop.col}`,
      );
    }
    if (result.stop.type === "close_block") {
      const name = result.stop.content.replace(/^\//, "").trim();
      throw new Error(
        `Mismatched close "{{/${name}}}" with no opening block at line ${result.stop.line}, column ${result.stop.col}`,
      );
    }
  }
  return result.nodes;
}

// ---------- Path resolution ----------

function walk(obj: unknown, segments: string[]): unknown {
  let cur: unknown = obj;
  for (const seg of segments) {
    if (cur === null || cur === undefined) return undefined;
    if (typeof cur !== "object") return undefined;
    cur = (cur as Record<string, unknown>)[seg];
  }
  return cur;
}

function resolvePath(path: string, ctx: RenderContext): unknown {
  if (path === "this") return ctx.current;
  if (path === "@index") return ctx.index;

  let segments = path.split(".");
  let base: unknown;

  if (segments[0] === "this") {
    base = ctx.current;
    segments = segments.slice(1);
    return walk(base, segments);
  }

  const fromCurrent = walk(ctx.current, segments);
  if (fromCurrent === undefined && ctx.current !== ctx.root) {
    const fromRoot = walk(ctx.root, segments);
    if (fromRoot !== undefined) return fromRoot;
  }
  return fromCurrent;
}

// ---------- Truthiness & scalarization ----------

function isTruthy(v: unknown): boolean {
  if (v === null || v === undefined || v === false || v === 0 || v === "") return false;
  if (Array.isArray(v) && v.length === 0) return false;
  return true;
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function scalarize(value: unknown, path: string, line: number, col: number): string {
  if (value === null || value === undefined) return "";
  if (typeof value === "string") return value;
  if (typeof value === "number") return String(value);
  if (typeof value === "boolean") return String(value);
  if (typeof value === "function") {
    throw new Error(
      `Cannot render function value for "{{${path}}}" at line ${line}, column ${col}`,
    );
  }
  if (typeof value === "object") {
    if (Array.isArray(value)) return "";
    throw new Error(
      `Cannot render object value for "{{${path}}}" at line ${line}, column ${col}`,
    );
  }
  return String(value);
}

// ---------- Renderer ----------

function renderNodes(nodes: Node[], ctx: RenderContext): string {
  let out = "";
  for (const node of nodes) {
    out += renderNode(node, ctx);
  }
  return out;
}

function renderNode(node: Node, ctx: RenderContext): string {
  switch (node.kind) {
    case "text":
      return node.text;
    case "interp": {
      const value = resolvePath(node.path, ctx);
      const scalar = scalarize(value, node.path, node.line, node.col);
      return node.escaped ? escapeHtml(scalar) : scalar;
    }
    case "if": {
      const value = resolvePath(node.path, ctx);
      if (isTruthy(value)) {
        return renderNodes(node.children, ctx);
      }
      return node.elseChildren ? renderNodes(node.elseChildren, ctx) : "";
    }
    case "each": {
      const value = resolvePath(node.path, ctx);
      if (!Array.isArray(value) || value.length === 0) {
        return node.elseChildren ? renderNodes(node.elseChildren, ctx) : "";
      }
      let out = "";
      for (let idx = 0; idx < value.length; idx++) {
        const childCtx: RenderContext = {
          current: value[idx],
          root: ctx.root,
          index: idx,
        };
        out += renderNodes(node.children, childCtx);
      }
      return out;
    }
  }
}

// ---------- Public API ----------

export function render(template: string, data: unknown): string {
  const tokens = tokenize(template);
  const ast = parse(tokens);
  const ctx: RenderContext = { current: data, root: data, index: undefined };
  return renderNodes(ast, ctx);
}

#!/usr/bin/env bun
import { render } from "./engine.ts";

function fail(msg: string): never {
  process.stderr.write(`error: ${msg}\n`);
  process.exit(1);
}

const args = process.argv.slice(2);

if (args.length !== 2) {
  fail("usage: bun run src/cli.ts TEMPLATE_FILE DATA.json");
}

const [templatePath, dataPath] = args;

let templateText: string;
try {
  templateText = await Bun.file(templatePath).text();
} catch (e) {
  fail(`cannot read template file "${templatePath}": ${(e as Error).message}`);
}

let dataText: string;
try {
  dataText = await Bun.file(dataPath).text();
} catch (e) {
  fail(`cannot read data file "${dataPath}": ${(e as Error).message}`);
}

let data: unknown;
try {
  data = JSON.parse(dataText);
} catch (e) {
  fail(`cannot parse JSON in "${dataPath}": ${(e as Error).message}`);
}

let output: string;
try {
  output = render(templateText, data);
} catch (e) {
  fail((e as Error).message);
}

process.stdout.write(output);

