import { test, expect } from "bun:test";
import { render } from "../src/engine.ts";

// --- interpolation ---

test("escaped interpolation escapes HTML", () => {
  expect(render("{{x}}", { x: '<a>&"\'</a>' })).toBe("&lt;a&gt;&amp;&quot;&#39;&lt;/a&gt;");
});

test("triple-brace is unescaped", () => {
  expect(render("{{{x}}}", { x: "<b>" })).toBe("<b>");
});

test("dotted path", () => {
  expect(render("{{a.b.c}}", { a: { b: { c: 7 } } })).toBe("7");
});

test("missing value renders empty", () => {
  expect(render("[{{nope}}]", {})).toBe("[]");
});

test("null and undefined render empty", () => {
  expect(render("[{{a}}][{{b}}]", { a: null, b: undefined })).toBe("[]");
});

test("booleans and numbers render", () => {
  expect(render("{{a}} {{b}}", { a: true, b: 42 })).toBe("true 42");
});

// --- if ---

test("if true branch", () => {
  expect(render("{{#if x}}yes{{/if}}", { x: 1 })).toBe("yes");
});

test("if false branch empty", () => {
  expect(render("{{#if x}}yes{{/if}}", { x: 0 })).toBe("");
});

test("if else", () => {
  expect(render("{{#if x}}A{{else}}B{{/if}}", { x: false })).toBe("B");
});

test("if nested", () => {
  expect(
    render("{{#if a}}{{#if b}}AB{{else}}A{{/if}}{{/if}}", { a: 1, b: 0 }),
  ).toBe("A");
});

test("if empty array is false", () => {
  expect(render("{{#if xs}}Y{{/if}}", { xs: [] })).toBe("");
});

test("if non-empty object is true", () => {
  expect(render("{{#if o}}Y{{/if}}", { o: { k: 1 } })).toBe("Y");
});

// --- each ---

test("each iterates", () => {
  expect(render("{{#each xs}}{{this}},{{/each}}", { xs: [1, 2, 3] })).toBe("1,2,3,");
});

test("each @index", () => {
  expect(render("{{#each xs}}{{@index}}:{{this}} {{/each}}", { xs: ["a", "b"] })).toBe(
    "0:a 1:b ",
  );
});

test("each else on empty", () => {
  expect(render("{{#each xs}}item{{else}}none{{/each}}", { xs: [] })).toBe("none");
});

test("each else on missing", () => {
  expect(render("{{#each xs}}item{{else}}none{{/each}}", {})).toBe("none");
});

test("each path falls back to root", () => {
  const tpl = "{{#each xs}}{{this}}-{{root}} {{/each}}";
  expect(render(tpl, { xs: [1, 2], root: "R" })).toBe("1-R 2-R ");
});

test("each nested loops", () => {
  const tpl = "{{#each outer}}{{#each inner}}{{this}}{{/each}}|{{/each}}";
  expect(render(tpl, { outer: [{ inner: ["a", "b"] }, { inner: ["c"] }] })).toBe("ab|c|");
});

test("each nested @index independent", () => {
  const tpl = "{{#each o}}{{@index}}:{{#each i}}{{@index}}{{/each}};{{/each}}";
  expect(render(tpl, { o: [{ i: [10, 20] }, { i: [30] }] })).toBe("0:01;1:0;");
});

// --- comments & whitespace ---

test("comment emits nothing", () => {
  expect(render("a{{! hidden }}b", {})).toBe("ab");
});

test("whitespace preserved", () => {
  expect(render("  line1\n  {{x}}\n  line3", { x: "X" })).toBe("  line1\n  X\n  line3");
});

// --- errors ---

test("object value throws", () => {
  expect(() => render("{{o}}", { o: { a: 1 } })).toThrow(/object/);
});

test("function value throws", () => {
  expect(() => render("{{f}}", { f: () => 1 })).toThrow(/function/);
});

test("unknown block throws", () => {
  expect(() => render("{{#foo x}}{{/foo}}", {})).toThrow(/Unknown block/);
});

test("mismatched close throws", () => {
  expect(() => render("{{#if x}}{{/each}}", { x: 1 })).toThrow(/Mismatched/);
});

test("unclosed block throws", () => {
  expect(() => render("{{#if x}}oops", { x: 1 })).toThrow(/Unclosed/);
});

test("duplicate else throws", () => {
  expect(() => render("{{#if x}}A{{else}}B{{else}}C{{/if}}", { x: 1 })).toThrow(/Duplicate/);
});

test("else outside block throws", () => {
  expect(() => render("A{{else}}B", {})).toThrow(/outside/);
});

test("close without open throws", () => {
  expect(() => render("{{/if}}", {})).toThrow(/Mismatched close/);
});

test("error includes line and column", () => {
  expect(() => render("\n\n{{#if x}}\noops", { x: 1 })).toThrow(/line 3/);
});

